#!/bin/bash
# GENERATED by sandboxctl. Do not edit by hand.
set -e
log() { echo "[Sandbox] $*"; }
mkdir -p /var/log

# 1. Ollama
log "Starting Ollama..."
ollama serve > /var/log/ollama.log 2>&1 &
until curl -s http://127.0.0.1:11434/api/tags > /dev/null 2>&1; do sleep 1; done
log "Ollama is ready."
IFS=',' read -ra MODELS <<< "$OLLAMA_MODEL,$OLLAMA_EXTRA_MODELS"
for MODEL in "${MODELS[@]}"; do
  [ -z "$MODEL" ] && continue
  if ! ollama list | grep -q "$MODEL"; then log "Pulling model $MODEL..."; ollama pull "$MODEL"; else log "Model $MODEL ready."; fi
done
nohup curl -s http://127.0.0.1:11434/api/generate -d "{\"model\": \"$OLLAMA_MODEL\", \"prompt\": \"ready\", \"stream\": false, \"options\": {\"num_ctx\": 32768}}" > /dev/null 2>&1 &

# 2. Idempotent TypeScript provisioner (git, VS Code workspace settings, MCP, T3 link)
if [ -f /opt/the-forge/dist/src/cli.js ]; then
  log "Running TypeScript provisioner..."
  node /opt/the-forge/dist/src/cli.js provision || true
fi

# 4. Token-Saver
TS_BIN=/root/.gemini/config/plugins/token-saver/bin/token-saver
[ -f "$TS_BIN" ] && chmod +x "$TS_BIN" && ln -sf "$TS_BIN" /usr/local/bin/token-saver
mkdir -p /root/.token-saver
[ -f /root/.token-saver/config.json ] || echo '{"enabled":true,"min_compression_ratio":0.05,"wrap_timeout":300}' > /root/.token-saver/config.json
[ -f /root/.gemini/config/hooks.json ] || { [ -f /root/.gemini/config/plugins/token-saver/hooks.json ] && cp /root/.gemini/config/plugins/token-saver/hooks.json /root/.gemini/config/hooks.json; } || true

# 5. Link config into every T3 Antigravity profile (every 2s)
nohup bash -c 'while true; do for p in /root/.t3/userdata/providers/antigravity/*; do [ -d "$p" ] || continue; mkdir -p "$p/config"; for f in mcp_config.json rules skills plugins hooks.json; do [ -e /root/.gemini/config/$f ] && ln -sfn /root/.gemini/config/$f "$p/config/$f"; done; done; sleep 2; done' > /var/log/t3-sync.log 2>&1 &

# 6. Buddy (self-healing, hot reload)
if [ -d /projects/buddy ]; then
  log "Starting Buddy supervisor..."
  nohup bash -c 'cd /projects/buddy; [ -d node_modules ] || npm install; while true; do echo "[$(date +%T)] [Buddy] launching tsx watch" >> /var/log/buddy.log; CHOKIDAR_USEPOLLING=1 npx tsx watch src/index.ts >> /var/log/buddy.log 2>&1; echo "[$(date +%T)] [Buddy] exited ($?); restarting in 3s" >> /var/log/buddy.log; sleep 3; done' > /dev/null 2>&1 &
fi

# 7. T3 (ensure binary exists inside /root/.t3 volume)
if [ ! -x /root/.local/bin/t3 ] && [ ! -x /usr/local/bin/t3 ]; then
  T3_EXISTING=$(ls -1 /root/.t3/runtime/versions/*/t3 2>/dev/null | tail -n 1)
  if [ -n "$T3_EXISTING" ]; then
    ln -sf "$T3_EXISTING" /usr/local/bin/t3
  else
    log "Installing T3 runtime into volume..."
    curl -fsSL https://t3.codes/install.sh | bash || true
  fi
fi
log "Starting T3 on port 3773..."
# Unset ANTHROPIC_API_KEY so T3 uses the claude.ai subscription login in /root/.claude
nohup env -u ANTHROPIC_API_KEY t3 serve --host 0.0.0.0 > /var/log/t3.log 2>&1 &

# 8. ComfyUI (bootstraps on first run)
start_comfyui() {
  if [ ! -f /root/comfyui/main.py ]; then
    echo "[ComfyUI] Cloning..."
    git clone https://github.com/comfyanonymous/ComfyUI.git /tmp/comfyui-clone
    cp -a /tmp/comfyui-clone/. /root/comfyui/ && rm -rf /tmp/comfyui-clone
  fi
  if [ ! -x /root/comfyui/.venv/bin/python ] || ! /root/comfyui/.venv/bin/python -c "import torch" >/dev/null 2>&1; then
    echo "[ComfyUI] Creating Python 3.12 venv..."
    export PATH="/root/.local/bin:$PATH"
    uv venv /root/comfyui/.venv --python 3.12 --clear
    uv pip install --python /root/comfyui/.venv/bin/python torch torchvision torchaudio --index-url https://download.pytorch.org/whl/cu128
    uv pip install --python /root/comfyui/.venv/bin/python -r /root/comfyui/requirements.txt
  fi
  cd /root/comfyui
  exec /root/comfyui/.venv/bin/python main.py --listen 0.0.0.0 --port 8188
}
( start_comfyui ) > /var/log/comfyui.log 2>&1 &

# 9. Preview landing server + Caddy proxy
if [ -f /opt/the-forge/dist/src/cli.js ]; then
  nohup node /opt/the-forge/dist/src/cli.js preview /projects > /var/log/preview.log 2>&1 &
fi
nohup caddy run --config /etc/caddy/Caddyfile > /var/log/caddy.log 2>&1 &

# 10. VS Code tunnel + default pnpm & TBE extension settings (first run needs a one-time login: the-forge tunnel-login)
mkdir -p /root/.vscode-server/data/Machine /projects/.vscode
VSCODE_SETTINGS='{"npm.packageManager":"pnpm","remote.extensionKind":{"local.tbe-vscode":["workspace"]}}'
[ -f /root/.vscode-server/data/Machine/settings.json ] || echo "$VSCODE_SETTINGS" > /root/.vscode-server/data/Machine/settings.json
[ -f /projects/.vscode/settings.json ] || echo "$VSCODE_SETTINGS" > /projects/.vscode/settings.json
[ -f /projects/.vscode/extensions.json ] || echo '{"recommendations":["local.tbe-vscode"]}' > /projects/.vscode/extensions.json
if [ -d /root/.vscode/cli ] && [ -n "$(ls -A /root/.vscode/cli 2>/dev/null)" ]; then
  log "Starting VS Code tunnel..."
  nohup code tunnel --accept-server-license-terms --name ai-sandbox > /var/log/vscode-tunnel.log 2>&1 &
else
  log "VS Code tunnel not signed in yet. Run: npx tsx src/cli.ts tunnel-login"
fi

log "Environment initialized."
exec "$@"
